const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Namibia'))
    .geometry();

  // Target period: Feb 21-28, 2019
  const target_start = '2019-02-21';
  const target_end = '2019-03-01';

  // Long-term reference: Feb 21-28, 2003-2017
  const years = ee.List.sequence(2003, 2017);

  // 2. Data Acquisition using MOD13Q1 (16-day NDVI product)
  const modis = ee.ImageCollection('MODIS/061/MOD13Q1')
    .select('NDVI')
    .filterBounds(namibia);

  // Get 2019 data
  const target_col = modis
    .filterDate(target_start, target_end);

  const target_size = target_col.size().getInfo();
  console.log(`2019 Images found: ${target_size}`);

  if (target_size === 0) {
    console.log("No data for Feb 21-28, 2019");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate 2019 mean
  const target_mean_img = target_col.mean();

  // Check pixel count
  const target_count = target_mean_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2019 Valid pixels: ${target_count}`);

  if (target_count === 0) {
    console.log("No valid pixels for 2019 after processing");
    console.log("<answer>C2</answer>");
    return;
  }

  const target_ndvi = target_mean_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Scale NDVI (MODIS NDVI is scaled by 10000)
  const target_ndvi_scaled = target_ndvi / 10000;

  console.log(`2019 NDVI: ${target_ndvi_scaled.toFixed(4)}`);

  // 4. Calculate long-term average (2003-2017)
  const long_term_list = years.map(function(year) {
    const y = ee.Number(year);
    const start = ee.Date.fromYMD(y, 2, 21);
    const end = ee.Date.fromYMD(y, 3, 1);

    const yearly_col = modis.filterDate(start, end);
    return yearly_col.mean();
  });

  const long_term_col = ee.ImageCollection.fromImages(long_term_list);
  const long_term_size = long_term_col.size().getInfo();
  console.log(`Long-term images: ${long_term_size}`);

  if (long_term_size === 0) {
    console.log("No long-term reference data");
    console.log("<answer>C1</answer>");
    return;
  }

  const long_term_mean = long_term_col.mean();

  const long_term_count = long_term_mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Long-term valid pixels: ${long_term_count}`);

  if (long_term_count === 0) {
    console.log("No valid pixels for long-term average");
    console.log("<answer>C2</answer>");
    return;
  }

  const long_term_ndvi = long_term_mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const long_term_ndvi_scaled = long_term_ndvi / 10000;

  console.log(`Long-term NDVI (2003-2017): ${long_term_ndvi_scaled.toFixed(4)}`);

  // 5. Validation & Final Answer
  if (target_ndvi_scaled === null || long_term_ndvi_scaled === null ||
      isNaN(target_ndvi_scaled) || isNaN(long_term_ndvi_scaled) ||
      target_ndvi_scaled < -1 || target_ndvi_scaled > 1 ||
      long_term_ndvi_scaled < -1 || long_term_ndvi_scaled > 1) {
    console.log("Invalid NDVI values detected");
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = target_ndvi_scaled - long_term_ndvi_scaled;
  console.log(`Difference (2019 - long-term): ${difference.toFixed(4)}`);

  if (target_ndvi_scaled < long_term_ndvi_scaled) {
    console.log("2019 vegetation health was WORSE than long-term average");
    console.log("<answer>A</answer>");
  } else {
    console.log("2019 vegetation health was NOT worse than long-term average");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
